const body = $input.item.json.body || $input.item.json;
return {
  json: {
    job_id: body.job_id,
    video_id: body.video_id,
    brief: body.brief || {},
    script: body.script || {},
    prompt_version: 'scene-planner/v1'
  }
};

const input = $input.item.json;
const brief = input.brief || {};
const script = input.script || {};
const totalDur = brief.targetDurationSeconds || 30;

// Generate structured scene plan
const scenes = [
  {
    position: 1,
    purpose: 'Hook Scene',
    narration: script.hook || 'المقدمة والخطاف',
    onScreenText: brief.workingTitle || 'فيديو مميز',
    visualDescription: 'لقطة افتتاحية سينمائية جذابة تجذب انتباه المشاهد',
    visualPrompt: 'Cinematic wide establishing shot, high quality lighting, 8k resolution, engaging dynamic composition',
    mediaStrategy: 'AI_VIDEO',
    durationSeconds: Math.max(3, Math.round(totalDur * 0.25))
  },
  {
    position: 2,
    purpose: 'Core Explanation',
    narration: 'المحتوى والشرح التوضيحي الرئيسي',
    onScreenText: 'خطوات العمل',
    visualDescription: 'رسوم متحركة موشن جرافيك توضح الفكرة بسلاسة',
    visualPrompt: 'Clean modern 3D motion graphics isometric elements, glowing accents, premium dark backdrop',
    mediaStrategy: 'MOTION_GRAPHICS',
    durationSeconds: Math.max(4, Math.round(totalDur * 0.5))
  },
  {
    position: 3,
    purpose: 'Outro & CTA',
    narration: brief.callToAction || 'شارك الفيديو وتابع الحساب',
    onScreenText: 'تابع للمزيد',
    visualDescription: 'لقطة ختامية مميزة مع شعار المنصة والدعوة للمتابعة',
    visualPrompt: 'High aesthetic cinematic shot with warm ambient glow, minimalist modern studio setup',
    mediaStrategy: 'AI_IMAGE',
    durationSeconds: Math.max(3, totalDur - Math.round(totalDur * 0.25) - Math.round(totalDur * 0.5))
  }
];

return {
  json: {
    job_id: input.job_id,
    video_id: input.video_id,
    stage: 'PLAN_READY',
    scenes: scenes
  }
};
